"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError

# ---
def contact_rows(students):
    """Text rows of name, section and email, by name."""
    if not students:
        raise ProjectError("no students for contact sheet")
    ordered = sorted(students, key=_name_key)
    cells = [_cells(pupil) for pupil in ordered]
    widths = [max(map(len, cols)) for cols in zip(*cells)]
    return [_line(row, widths) for row in cells]


def _name_key(pupil):
    return pupil.display_name


def _cells(pupil):
    if not pupil.email:
        name = pupil.display_name
        raise ProjectError(f"no email for {name}")
    return (pupil.display_name, pupil.section, pupil.email)


def _line(row, widths):
    pairs = zip(row, widths)
    padded = [cell.ljust(wide) for cell, wide in pairs]
    return "  ".join(padded).rstrip()
